import { Card, Stack, Typography } from '@mui/material'

import { type ClubReview } from 'src/responses/review'

import ReviewKeyword from '../ReviewKeyword'
import SemesterChip from '../SemesterChip'

interface ReviewCardProps extends ClubReview {
  onClick?: React.MouseEventHandler<HTMLDivElement>
}

const ReviewCard = (review: ReviewCardProps) => {
  const { clubName, clubDescription, year, semester, content, keywords, recommendedPerson, userNickname } = review
  const isReviewClickable = Boolean(review.onClick)

  return (
    <Card
      onClick={review.onClick}
      sx={{
        p: '34px 36px 13px',
        borderRadius: '10px',
        boxShadow: '0px 2px 2px 0px rgba(159, 162, 191, 0.25), 0px 9px 16px 0px rgba(159, 162, 191, 0.18)',
        display: 'flex',
        flexDirection: 'column',
        gap: '14px',
        cursor: isReviewClickable ? 'pointer' : 'default'
      }}
    >
      <Stack direction="row" justifyContent="space-between" alignItems="flex-start">
        <Stack spacing="3px">
          {clubName && (
            <Typography
              sx={{
                fontFamily: 'Pretendard',
                fontSize: '13px',
                fontWeight: 400,
                color: '#000000',
                lineHeight: 1.2
              }}
            >
              {clubName}
            </Typography>
          )}
          {clubDescription && (
            <Typography
              sx={{
                fontFamily: 'Pretendard',
                fontSize: '14px',
                fontWeight: 400,
                color: 'rgba(34, 51, 84, 0.7)',
                lineHeight: 1.2
              }}
            >
              {clubDescription}
            </Typography>
          )}
        </Stack>
        <SemesterChip year={year} semester={semester} />
      </Stack>

      <Typography
        sx={{
          fontFamily: 'Pretendard',
          fontSize: '13px',
          lineHeight: '1.5',
          color: '#000000'
        }}
      >
        {content}
      </Typography>

      {keywords && keywords.length > 0 && (
        <Stack spacing="3px">
          {keywords.map(keyword => (
            <ReviewKeyword key={keyword.id} keyword={keyword} />
          ))}
        </Stack>
      )}

      <Stack direction="row" justifyContent="space-between" alignItems="center" sx={{ pt: 0.5 }}>
        <Typography
          sx={{
            fontFamily: 'Pretendard',
            fontSize: '13px',
            color: '#FF9393'
          }}
        >
          {recommendedPerson ? `# ${recommendedPerson}에게 추천!` : ''}
        </Typography>
        <Typography
          sx={{
            fontFamily: 'Pretendard',
            fontSize: '14px',
            color: '#B1B1B1'
          }}
        >
          from. {userNickname}
        </Typography>
      </Stack>
    </Card>
  )
}

export default ReviewCard
