import Masonry from 'react-masonry-css'

import { Box, Card, Typography } from '@mui/material'

import ReviewCard from 'src/components/ReviewCard'

import { type ClubReview } from 'src/responses/review'

const breakpointColumns = {
  default: 3,
  960: 2,
  600: 1
}

interface ReviewGridProps {
  reviews: ClubReview[]
  onReviewCardClick?: (clubId: number) => void
}

const ReviewGrid: React.FC<ReviewGridProps> = ({ reviews, onReviewCardClick }) => {
  return reviews && reviews.length > 0 ? (
    <Box
      component={Masonry}
      breakpointCols={reviews.length > 3 ? breakpointColumns : reviews.length}
      sx={{
        display: 'flex',
        marginLeft: '-16px',
        width: 'auto',
        '& > div': {
          paddingLeft: '16px',
          backgroundClip: 'padding-box'
        }
      }}
    >
      {reviews.map(review => (
        <Box key={review.id} mb={2}>
          <ReviewCard
            {...review}
            onClick={onReviewCardClick ? () => onReviewCardClick(review.clubId) : undefined}
          />
        </Box>
      ))}
    </Box>
  ) : (
    <Card sx={{ p: 2 }}>
      <Typography color="text.secondary">아직 작성된 후기가 없어요.</Typography>
    </Card>
  )
}

export default ReviewGrid
